import OpenAI from "openai";

// after:  litellm --model gpt-4o-mini   (proxy on port 4000)
const client = new OpenAI({ baseURL: "http://localhost:4000", apiKey: "sk-anything" });
const r = await client.chat.completions.create({ model: "gpt-4o-mini", messages: [{ role: "user", content: "Say hello" }] });
console.log(r.choices[0].message.content);
